package engine

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"strconv"
	"time"
)

// StaleReason is the rejection of a command whose preview digest no longer matches (D-056).
const StaleReason = "state changed since the preview; preview again"

// PreviewDigest is the canonical digest of handling in on s, whose result is r (D-056). A dry run returns it, and a
// command that carries it as InputMeta.Expect is handled only if handling it now gives the same digest.
//
// The canonical form (version 2) binds the project, its pipeline version, the command's parameters, the actual
// approval step for an approval decision, the abort's target and both of its D-020 outcomes, and the consequential
// effects: every transition and notification, with the ids of existing deployments and holds and the semantic expiry
// of a new hold. A new deployment's effect also binds what decides its later behaviour: the release it replaces (the
// rollback target and what a verified abort restores), its gate failure policy and its gate steps; the rest of its
// config follows from the pipeline version. Windows bind through the effects they allow or block now. It leaves out
// the input's id and actor, timestamps, ids generated by this handling, actor-derived text and stuck markers, so an
// unchanged state always gives the same digest.
func PreviewDigest(s State, in Input, r Result) string {
	type effect struct {
		Type, Stage, Deployment, Release, Phase, State, Kind, Dimension, Source, Hold, Outcome, Candidacy, Urgency, Expires string
		Previous, Policy                                                                                                    string
		Gate                                                                                                                []string
		Index                                                                                                               *int
	}
	var c struct {
		V             int
		Project       string
		Version       int
		Command       string
		Params        map[string]any
		Step          int
		Target        map[string]string
		Effects       []effect
		Notifications []effect
	}
	c.V, c.Project, c.Version, c.Step = 2, s.Project, s.PipelineVersion, -1
	c.Params = map[string]any{}
	switch in := in.(type) {
	case AddHold:
		c.Command, c.Params = "AddHold", map[string]any{"stage": in.Stage, "dimensions": in.Dimensions, "reason": in.Reason, "expires": expiry(in.ExpiresAt)}
	case ClearHold:
		c.Command, c.Params = "ClearHold", map[string]any{"stage": in.Stage, "hold": in.Hold, "dimension": in.Dimension, "reason": in.Reason}
	case ManualDeploy:
		c.Command, c.Params = "ManualDeploy", map[string]any{"stage": in.Stage, "release": in.Release, "reason": in.Reason}
	case Abort:
		c.Command, c.Params = "Abort", map[string]any{"stage": in.Stage, "deployment": in.Deployment, "reason": in.Reason}
		if d, ok := s.Deployment(in.Deployment); ok {
			// Both D-020 outcomes follow from these: the deploying abort's verified-live branches and the gate policy.
			c.Target = map[string]string{"phase": string(d.Phase), "kind": string(d.Kind), "release": d.Release,
				"previous": d.PreviousRelease, "policy": string(d.Config.OnGateFailure)}
		}
	case Approve:
		c.Command, c.Params = "Approve", map[string]any{"stage": in.Stage, "deployment": in.Deployment, "step": in.Step, "reason": in.Reason}
		c.Step = waitingIndex(s, in.Stage)
	case Reject:
		c.Command, c.Params = "Reject", map[string]any{"stage": in.Stage, "deployment": in.Deployment, "step": in.Step, "reason": in.Reason}
		c.Step = waitingIndex(s, in.Stage)
	}
	// Ids this handling generates are numbered in order of appearance, so they never depend on the stage counters. A
	// manual deployment's holds name its deployment before it is created, so all are numbered first.
	generated := map[string]string{}
	for _, t := range r.Transitions {
		switch t := t.(type) {
		case DeploymentCreated:
			generated[t.Deployment.ID] = "new-deployment-" + strconv.Itoa(len(generated))
		case HoldAdded:
			generated[t.Hold.ID] = "new-hold-" + strconv.Itoa(len(generated))
		}
	}
	id := func(v string) string {
		if g, ok := generated[v]; ok {
			return g
		}
		return v
	}
	for _, t := range r.Transitions {
		var e effect
		switch t := t.(type) {
		case DeploymentCreated:
			d := t.Deployment
			e = effect{Type: "deploymentCreated", Stage: d.Stage, Deployment: id(d.ID), Release: d.Release, Kind: string(d.Kind),
				Previous: d.PreviousRelease, Policy: string(d.Config.OnGateFailure), Gate: []string{}}
			for _, g := range d.Steps {
				e.Gate = append(e.Gate, g.Type)
			}
		case DeploymentPhaseChanged:
			e = effect{Type: "deploymentPhase", Stage: t.Stage, Deployment: id(t.Deployment), Phase: string(t.Phase)}
		case GateStepChanged:
			i := t.Index
			e = effect{Type: "stepChanged", Stage: t.Stage, Deployment: id(t.Deployment), Index: &i, State: string(t.State)}
		case HoldAdded:
			h := t.Hold
			e = effect{Type: "holdAdded", Stage: h.Stage, Hold: id(h.ID), Dimension: string(h.Dimension), Source: string(h.Source),
				Deployment: id(h.Deployment), Expires: expiry(h.ExpiresAt)}
		case HoldCleared:
			e = effect{Type: "holdCleared", Stage: t.Stage, Hold: id(t.Hold)}
		case OutcomeChanged:
			e = effect{Type: "outcome", Stage: t.Stage, Release: t.Release, Outcome: string(t.Outcome), Deployment: id(t.Deployment)}
		case CandidacyChanged:
			e = effect{Type: "candidacy", Stage: t.Stage, Release: t.Release, Candidacy: string(t.Candidacy)}
		case StagesChanged:
			e = effect{Type: "stagesChanged"}
		case ReleaseAdded:
			e = effect{Type: "releaseAdded", Release: t.Release.ID}
		default: // DeploymentStuck: an incidental marker
			continue
		}
		c.Effects = append(c.Effects, e)
	}
	for _, a := range r.Actions {
		if n, ok := a.(Notify); ok && n.Notification != NotifyDeploymentStuck {
			c.Notifications = append(c.Notifications, effect{Type: string(n.Notification), Stage: n.Stage, Deployment: id(n.Deployment),
				Release: n.Release, Hold: id(n.Hold), Dimension: string(n.Dimension), Urgency: string(n.Urgency)})
		}
	}
	raw, _ := json.Marshal(c) // strings, ints and string slices always marshal
	sum := sha256.Sum256(raw)
	return hex.EncodeToString(sum[:])
}

// expiry is a hold's expiry as the digest binds it: semantic, so it stays, unlike a creation time.
func expiry(t time.Time) string {
	if t.IsZero() {
		return ""
	}
	return t.UTC().Format(time.RFC3339Nano)
}

// waitingIndex is the index of the step the stage's active deployment is running or waiting at, or -1.
func waitingIndex(s State, stage string) int {
	if d, ok := s.Active(stage); ok {
		return liveStep(d)
	}
	return -1
}
